package br.edu.insper.tarefas;
import org.springframework.stereotype.Service; import java.util.List;
@Service public class TaskService { private final TaskRepository repository; public TaskService(TaskRepository repository){this.repository=repository;} public TaskRequests.Response create(TaskRequests.Create r){return TaskRequests.Response.from(repository.save(new Task(required(r.title()),r.description())));} public List<TaskRequests.Response> list(){return repository.findAll().stream().map(TaskRequests.Response::from).toList();} public TaskRequests.Response get(Long id){return TaskRequests.Response.from(find(id));} public TaskRequests.Response update(Long id,TaskRequests.Update r){Task t=find(id);if(r.status()==null)throw new IllegalArgumentException("Status obrigatório");t.update(required(r.title()),r.description(),r.status());return TaskRequests.Response.from(repository.save(t));} public void delete(Long id){repository.delete(find(id));} private Task find(Long id){return repository.findById(id).orElseThrow(()->new IllegalArgumentException("Tarefa não encontrada"));} private String required(String title){if(title==null||title.isBlank())throw new IllegalArgumentException("Título obrigatório");return title.trim();}}
